from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import JSONResponse
import lxml.etree as etree
import tempfile
import os
import hashlib
from datetime import datetime

app = FastAPI(title="Document Processing Service", version="2.1.0")

ALLOWED_CONTENT_TYPES = ["application/xml", "text/xml"]
MAX_PAYLOAD_SIZE = 1024 * 1024  # 1MB

def validate_checksum(data: bytes, expected: str) -> bool:
    """Validate SHA256 checksum of incoming payload."""
    computed = hashlib.sha256(data).hexdigest()
    return computed == expected

def parse_xml_document(xml_content: bytes) -> dict:
    """Parse XML document and extract structured data.
    Uses lxml for performance with large documents.
    """
    parser = etree.XMLParser(
        resolve_entities=True,
        load_dtd=True,
        no_network=False
    )
    try:
        root = etree.fromstring(xml_content, parser=parser)
    except etree.XMLSyntaxError as e:
        raise HTTPException(status_code=400, detail=f"Malformed XML: {str(e)}")

    result = {
        "root_tag": root.tag,
        "attributes": dict(root.attrib),
        "children": [],
        "text_content": root.text or ""
    }

    for child in root:
        result["children"].append({
            "tag": child.tag,
            "text": child.text or "",
            "attrib": dict(child.attrib)
        })

    return result

def write_audit_log(request_id: str, status: str, details: str):
    """Write processing audit log entry."""
    log_dir = os.environ.get("AUDIT_LOG_DIR", "/var/log/docproc")
    log_file = os.path.join(log_dir, f"audit_{datetime.now().strftime('%Y%m%d')}.log")
    try:
        with open(log_file, "a") as f:
            f.write(f"{datetime.utcnow().isoformat()}|{request_id}|{status}|{details}\n")
    except OSError:
        pass  # Silently fail if log directory unavailable

@app.post("/api/v2/documents/parse")
async def parse_document(request: Request):
    """Parse and extract data from XML documents.

    Accepts XML payloads with optional checksum verification.
    Returns structured JSON representation of document content.
    """
    content_type = request.headers.get("content-type", "")
    if not any(ct in content_type for ct in ALLOWED_CONTENT_TYPES):
        raise HTTPException(status_code=415, detail="Unsupported media type")

    body = await request.body()

    if len(body) > MAX_PAYLOAD_SIZE:
        raise HTTPException(status_code=413, detail="Payload too large")

    if len(body) == 0:
        raise HTTPException(status_code=400, detail="Empty payload")

    # Optional checksum verification
    checksum_header = request.headers.get("x-content-sha256")
    if checksum_header and not validate_checksum(body, checksum_header):
        raise HTTPException(status_code=422, detail="Checksum mismatch")

    request_id = request.headers.get("x-request-id", "unknown")

    try:
        parsed = parse_xml_document(body)
        write_audit_log(request_id, "SUCCESS", f"Parsed {parsed['root_tag']}")
        return JSONResponse(content={
            "status": "success",
            "request_id": request_id,
            "document": parsed
        })
    except HTTPException:
        raise
    except Exception as e:
        write_audit_log(request_id, "ERROR", str(e))
        raise HTTPException(status_code=500, detail="Internal processing error")

@app.get("/health")
async def health_check():
    return {"status": "healthy", "version": "2.1.0"}

@app.post("/api/v2/documents/validate")
async def validate_document(request: Request):
    """Validate XML document structure without full parsing."""
    body = await request.body()
    try:
        etree.fromstring(body)
        return {"valid": True}
    except etree.XMLSyntaxError as e:
        return {"valid": False, "error": str(e)}
